def assemble_oof(n,folds):
    if type(n) is not int or n<0:raise ValueError('invalid row count')
    result=[None]*n;seen=set()
    for indices,values in folds:
        if len(indices)!=len(values):raise ValueError('length mismatch')
        for i,value in zip(indices,values):
            if type(i) is not int or not 0<=i<n or i in seen:raise ValueError('overlapping fold')
            seen.add(i);result[i]=value
    if len(seen)!=n:raise ValueError('incomplete coverage')
    return result

