import math
def nested_report(folds):
    if not folds:raise ValueError('no folds')
    names=[];scores=[]
    for candidates in folds:
        if not candidates:raise ValueError('no candidates')
        for record in candidates.values():
            if not record['inner'] or any(not math.isfinite(x) for x in record['inner']+[record['outer']]):raise ValueError('invalid scores')
        chosen=min(candidates,key=lambda k:(-sum(candidates[k]['inner'])/len(candidates[k]['inner']),k))
        names.append(chosen);scores.append(candidates[chosen]['outer'])
    return names,sum(scores)/len(scores)

